const e = $json.execution || {};
const wf = $json.workflow || {};
const err = e.error || $json.trigger?.error || {};
const when = new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' });
let hint = '';
const msg = String(err.message || 'Unknown error');
if (/google|drive|oauth|invalid_grant|401/i.test(msg) && /drive|google/i.test((e.lastNodeExecuted || '') + msg)) {
  hint = '\nLikely cause: the Google Drive connection is missing or expired. Open the credential "Google Drive: backups" in n8n and sign in again. The encrypted file still reached Telegram if this was the daily backup.';
}
const lines = [
  'WORKFLOW FAILED: ' + (wf.name || 'unknown'),
  'Step: ' + (e.lastNodeExecuted || 'n/a'),
  'Error: ' + msg.slice(0, 700),
  'Time: ' + when + ' IST',
];
if (e.url) lines.push('Open: ' + e.url);
return [{ json: { text: lines.join('\n') + hint } }];
